{"path":"/tmp/claude-0/-home-user-World-Best--Agentic-Architecture/5c299c61-7b18-5ef4-98fd-94b785187bee/scratchpad/runs/ultra-core-polymath-v2/workspaces/math-grid-paths__r1/compute_paths.py","content":"#!/usr/bin/env python3
"""Count paths from (0,0) to (12,12) avoiding blocked cells."""

blocked = {(3,3), (4,7), (7,4), (8,8), (10,2), (2,10), (6,6)}

# DP table: dp[x][y] = number of ways to reach (x,y)
# Grid is 0..12 inclusive, so 13x13
dp = [[0] * 13 for _ in range(13)]

# Starting point
if (0, 0) not in blocked:
    dp[0][0] = 1

for x in range(13):
    for y in range(13):
        if (x, y) in blocked:
            dp[x][y] = 0
            continue
        if x == 0 and y == 0:
            continue
        ways = 0
        if x > 0:
            ways += dp[x-1][y]
        if y > 0:
            ways += dp[x][y-1]
        dp[x][y] = ways

answer = dp[12][12]
print(f"Number of distinct paths: {answer}")

with open("answer.txt", "w") as f:
    f.write(str(answer))"}
